int main() {
    string ipAddress;
    cout << "Enter an IP address: ";
    getline(cin, ipAddress);

    // Regular expression to validate IP address
    regex pattern(R"(^\s*(?:\d{1,3}\.){3}\d{1,3}\s*$)");

    if (regex_match(ipAddress, pattern)) { // checks if string matches pattern
        // Splitting the IP address by "." to check each number
        size_t startPos = 0, endPos = 0;
        string token;
        for (int I = 0; I < 4; ++i) {
            endPos = ipAddress.find(".", startPos);
            token = ipAddress.substr(startPos, endPos - startPos);

            // Validating each group between the dots
            if (token.empty() || stoi(token) < 0 || stoi(token) > 255) {
                cout << "Invalid IP address." << endl;
                return 0;
            }
            startPos = endPos + 1;
        }
        cout << "Valid IP address." << endl;
    } else {
        cout << "Not a valid IP address." << endl;
    }

    return 0;
}

